CustomField.formula:
IF(
    OR(
        ISPICKVAL(ParticipantType__c, "Individual"),
        TEXT(ParticipantType__c) = "",
        ISBLANK(TEXT(ParticipantType__c))
    ),
    /* For Individual or blank Participant Type */
    IF(
        Prefer_Nickname__c && NOT(ISBLANK(Nickname__c)),
        Nickname__c,
        First_Name__c & " " & Last_Name__c
    ),
    /* For Company or other types */
    Company__c
)
